    #[test]
    fn contenteditable_is_detected_and_inherited() {
        let mut w = fresh_window();
        let dom = StyledDom::create_from_dom(
            Dom::create_body().with_child(
                Dom::create_div()
                    .with_contenteditable(true)
                    .with_child(Dom::create_div()),
            ),
        );
        assert_eq!(dom.node_hierarchy.len(), 3);
        w.layout_results
            .insert(DomId::ROOT_ID, bare_layout_result(dom));

        assert!(!w.is_node_contenteditable_internal(DomId::ROOT_ID, NodeId::new(0)));
        assert!(w.is_node_contenteditable_internal(DomId::ROOT_ID, NodeId::new(1)));
        // The nested child is NOT directly editable...
        assert!(!w.is_node_contenteditable_internal(DomId::ROOT_ID, NodeId::new(2)));
        // ...but it inherits editability from its ancestor.
        assert!(w.is_node_contenteditable_inherited_internal(DomId::ROOT_ID, NodeId::new(2)));
    }

    // ==================================================================
    // Editable-buffer text collection
    // ==================================================================

    fn window_for(dom: StyledDom) -> LayoutWindow {
        let mut w = fresh_window();
        w.layout_results
            .insert(DomId::ROOT_ID, bare_layout_result(dom));
        w
    }

    fn text_of(w: &LayoutWindow, node: usize) -> String {
        let content = w.get_text_before_textinput(DomId::ROOT_ID, NodeId::new(node));
        w.extract_text_from_inline_content(&content)
    }

    /// U3-b: text the APP's generation changed under the carets moves them -
    /// the local caret and a peer alike - and a pass that changes nothing
    /// moves nothing.
    #[test]
    fn a_generation_that_changes_the_text_shifts_every_caret() {
        use azul_core::selection::{
            CursorAffinity, GraphemeClusterId, Selection, SelectionOwner, TextCursor,
        };

        fn editable(text: &str) -> StyledDom {
            StyledDom::create_from_dom(
                Dom::create_div()
                    .with_contenteditable(true)
                    .with_child(Dom::create_p().with_child(
                        Dom::create_text_do_not_use_without_block_level_wrapper(text),
                    )),
            )
        }
        fn at(byte: u32) -> TextCursor {
            TextCursor {
                cluster_id: GraphemeClusterId {
                    source_run: 0,
                    start_byte_in_run: byte,
                },
                affinity: CursorAffinity::Leading,
            }
        }

        let mut w = window_for(editable("hello world"));
        w.text_edit_manager
            .initialize_editing(at(6), DomId::ROOT_ID, NodeId::new(0), 77);
        let bob = SelectionOwner::new(2, 2);
        assert!(w
            .text_edit_manager
            .multi_cursor
            .as_mut()
            .unwrap()
            .set_owner_selections(bob, &[Selection::Cursor(at(8))]));
        // First pass: nothing to compare against yet - snapshot only.
        w.shift_carets_across_generation();
        assert_eq!(w.text_edit_manager.get_primary_cursor(), Some(at(6)));

        // The app's next generation carries a remote insert of "XX" at 0.
        w.layout_results
            .insert(DomId::ROOT_ID, bare_layout_result(editable("XXhello world")));
        w.shift_carets_across_generation();
        assert_eq!(w.text_edit_manager.get_primary_cursor(), Some(at(8)), "local");
        let peer = w
            .text_edit_manager
            .multi_cursor
            .as_ref()
            .unwrap()
            .selections
            .iter()
            .find(|s| s.owner == bob)
            .unwrap()
            .selection;
        assert_eq!(peer, Selection::Cursor(at(10)), "peer");

        // An unchanged generation moves nothing.
        w.shift_carets_across_generation();
        assert_eq!(w.text_edit_manager.get_primary_cursor(), Some(at(8)));

        // A delete spanning the local caret collapses it to the change start.
        // "XXhello world" -> "XXhorld" has two equally small explanations
        // (drop "ello w" keeping hello's 'o', or drop "ello w" keeping
        // world's 'o'); the diff takes the longest common PREFIX first, so
        // the change is bytes 3..9 and the caret lands on 3.
        w.layout_results
            .insert(DomId::ROOT_ID, bare_layout_result(editable("XXhorld")));
        w.shift_carets_across_generation();
        assert_eq!(w.text_edit_manager.get_primary_cursor(), Some(at(3)));
    }

    #[test]
    fn get_text_before_textinput_descends_through_block_and_inline_wrappers() {
        // `div[contenteditable] > p > text` is the shape the converted text
        // widgets, azul-writer and the contenteditable e2e fixtures all use.
        // Reading it as EMPTY made the first keystroke diff against "" and wipe
        // the value.
        let w = window_for(StyledDom::create_from_dom(
            Dom::create_div()
                .with_contenteditable(true)
                .with_child(Dom::create_p().with_child(
                    Dom::create_text_do_not_use_without_block_level_wrapper("hello"),
                )),
        ));
        assert_eq!(
            text_of(&w, 0),
            "hello",
            "a <p> wrapper must not hide the value"
        );
        assert_eq!(text_of(&w, 1), "hello", "and the <p> itself reads the same");

        // Inline wrappers count too — the buffer is the flattened inline content
        // of the subtree, not just its direct text children.
        let w =
            window_for(StyledDom::create_from_dom(
                Dom::create_div().with_child(
                    Dom::create_p()
                        .with_child(Dom::create_text_do_not_use_without_block_level_wrapper("a"))
                        .with_child(Dom::create_em().with_child(
                            Dom::create_text_do_not_use_without_block_level_wrapper("b"),
                        ))
                        .with_child(Dom::create_span().with_child(
                            Dom::create_text_do_not_use_without_block_level_wrapper("c"),
                        )),
                ),
            ));
        assert_eq!(text_of(&w, 0), "abc");
    }

    #[test]
    fn get_text_before_textinput_leaves_metadata_subtrees_out() {
        // `<head>` and the metadata elements are never rendered, so their text
        // must not leak into an editable value.
        let w = window_for(StyledDom::create_from_dom(
            Dom::create_div()
                .with_child(Dom::create_head().with_child(
                    Dom::create_text_do_not_use_without_block_level_wrapper("metadata"),
                ))
                .with_child(Dom::create_p().with_child(
                    Dom::create_text_do_not_use_without_block_level_wrapper("body"),
                )),
        ));
        assert_eq!(text_of(&w, 0), "body");
        assert_eq!(text_of(&w, 1), "", "a metadata container collects nothing");
    }

    #[test]
    fn collect_text_from_children_skips_a_contenteditable_false_island() {
        // The text widgets keep their placeholder prompt INSIDE the editable
        // container and wall it off with `contenteditable="false"` — the same
        // attribute that stops the inheritance walk. Collecting it would type the
        // prompt into the user's value.
        let w = window_for(StyledDom::create_from_dom(
            Dom::create_div()
                .with_contenteditable(true)
                .with_child(
                    Dom::create_p()
                        .with_attribute(AttributeType::ContentEditable(false))
                        .with_child(Dom::create_text_do_not_use_without_block_level_wrapper(
                            "Type here...",
                        )),
                )
                .with_child(Dom::create_p().with_child(
                    Dom::create_text_do_not_use_without_block_level_wrapper("real value"),
                )),
        ));
        assert_eq!(text_of(&w, 0), "real value");
        // The wall is about the parent's collection, not a global mute: asked
        // directly, the island still reports its own text.
        assert_eq!(text_of(&w, 1), "Type here...");
    }

    #[test]
    fn ifc_candidate_children_puts_the_carets_block_ahead_of_document_order() {
        use azul_core::selection::MultiCursorState;

        // `container > [placeholder p, value p]`: document order hands the IFC to
        // the placeholder, so `reshape_text_node` has to ask the caret first.
        let mut w = window_for(StyledDom::create_from_dom(
            Dom::create_div()
                .with_child(Dom::create_p().with_child(
                    Dom::create_text_do_not_use_without_block_level_wrapper("prompt"),
                ))
                .with_child(Dom::create_p().with_child(
                    Dom::create_text_do_not_use_without_block_level_wrapper("value"),
                )),
        ));

        assert_eq!(
            w.ifc_candidate_children(DomId::ROOT_ID, NodeId::new(0)),
            vec![
                NodeId::new(1),
                NodeId::new(3),
                NodeId::new(2),
                NodeId::new(4)
            ],
            "direct children in document order first, then deeper descendants"
        );

        // Caret on the TEXT LEAF of the second <p>: the block that owns it wins.
        w.text_edit_manager.multi_cursor = Some(MultiCursorState::new_with_cursor(
            TextCursor {
                cluster_id: GraphemeClusterId {
                    source_run: 0,
                    start_byte_in_run: 0,
                },
                affinity: CursorAffinity::Leading,
            },
            dnid(4),
            0,
        ));
        assert_eq!(
            w.ifc_candidate_children(DomId::ROOT_ID, NodeId::new(0)),
            vec![
                NodeId::new(3),
                NodeId::new(1),
                NodeId::new(2),
                NodeId::new(4)
            ],
            "the caret's block must be searched first"
        );
    }

    #[test]
    fn caret_blink_interval_falls_back_to_the_os_rate_and_honours_never_blink() {
        use crate::managers::text_edit::CURSOR_BLINK_INTERVAL;

        fn os_style(rate_ms: u32) -> Arc<azul_css::system::SystemStyle> {
            let mut style = azul_css::system::SystemStyle::default();
            style.input.caret_blink_rate_ms = rate_ms;
            Arc::new(style)
        }

        let mut w = window_with_fixture();
        let node = NodeId::new(1);

        // Nothing captured from the OS yet -> the 530 ms default.
        assert_eq!(
            w.caret_blink_interval_for(DomId::ROOT_ID, node),
            CURSOR_BLINK_INTERVAL
        );

        // With CSS silent, the OS rate is used verbatim.
        w.set_system_style(os_style(1200));
        assert_eq!(
            w.caret_blink_interval_for(DomId::ROOT_ID, node),
            Duration::from_millis(1200)
        );

        // Windows' INFINITE and GNOME's `cursor-blink = false` both mean
        // "never toggle".
        for never in [0, u32::MAX] {
            w.set_system_style(os_style(never));
            assert_eq!(
                w.caret_blink_interval_for(DomId::ROOT_ID, node),
                Duration::from_millis(u64::from(u32::MAX)),
                "caret_blink_rate_ms = {never} must not blink"
            );
        }

        // An explicit stylesheet value still wins over the OS.
        let mut styled = window_for(StyledDom::create_from_dom(
            Dom::create_div().with_css("caret-animation-duration: 250ms;"),
        ));
        styled.set_system_style(os_style(1200));
        assert_eq!(
            styled.caret_blink_interval_for(DomId::ROOT_ID, NodeId::new(0)),
            Duration::from_millis(250)
        );
    }

    // ==================================================================
    // Timers
    // ==================================================================

    extern "C" fn time_tick_0() -> Instant {
        Instant::Tick(azul_core::task::SystemTick { tick_counter: 0 })
    }

    extern "C" fn time_tick_1000() -> Instant {
        Instant::Tick(azul_core::task::SystemTick {
            tick_counter: 1_000,
        })
    }

    extern "C" fn time_tick_max() -> Instant {
        Instant::Tick(azul_core::task::SystemTick {
            tick_counter: u64::MAX,
        })
    }

    extern "C" fn time_system_now() -> Instant {
        Instant::now()
    }

    #[test]
    fn timer_add_get_remove_round_trips_and_overwrites_by_id() {
        let mut w = fresh_window();
        let id = TimerId { id: 1 };
        assert!(w.get_timer(&id).is_none());
        assert!(
            w.remove_timer(&id).is_none(),
            "removing an absent timer is None"
        );

        w.add_timer(id, Timer::default());
        assert!(w.get_timer(&id).is_some());
        assert!(w.get_timer_mut(&id).is_some());
        assert_eq!(w.get_timer_ids().len(), 1);

        // Re-adding the same id replaces rather than duplicates.
        w.add_timer(id, Timer::default());
        assert_eq!(w.get_timer_ids().len(), 1);

        assert!(w.remove_timer(&id).is_some());
        assert!(w.get_timer(&id).is_none());
        assert_eq!(w.get_timer_ids().len(), 0);
        // Double remove is a clean None, not a panic.
        assert!(w.remove_timer(&id).is_none());
    }

    #[test]
    fn timer_ids_survive_extreme_id_values() {
        let mut w = fresh_window();
        let lo = TimerId { id: 0 };
        let hi = TimerId { id: usize::MAX };
        w.add_timer(lo, Timer::default());
        w.add_timer(hi, Timer::default());
        assert_eq!(w.get_timer_ids().len(), 2);
        assert!(w.get_timer(&lo).is_some());
        assert!(w.get_timer(&hi).is_some());
        assert!(w.remove_timer(&hi).is_some());
        assert_eq!(w.get_timer_ids().len(), 1);
    }

    #[test]
    fn tick_timers_reports_every_registered_timer_regardless_of_the_clock() {
        let mut w = fresh_window();
        assert!(
            w.tick_timers(tick(0)).is_empty(),
            "no timers => nothing ready"
        );

        for i in 0..3 {
            w.add_timer(TimerId { id: i }, Timer::default());
        }
        // Pinned as CURRENT behaviour: `tick_timers` ignores `current_time` and
        // returns every registered id; readiness is decided by the caller.
        for now in [tick(0), tick(u64::MAX), Instant::now()] {
            let ready = w.tick_timers(now);
            assert_eq!(ready.len(), 3);
        }
    }

    #[test]
    fn time_until_next_timer_ms_is_none_without_timers() {
        let w = fresh_window();
        let cb = azul_core::task::GetSystemTimeCallback { cb: time_tick_0 };
        assert_eq!(
            w.time_until_next_timer_ms(&cb),
            None,
            "no timers => the caller may block indefinitely"
        );
    }

    #[test]
    fn time_until_next_timer_ms_reports_zero_for_an_overdue_timer() {
        let mut w = fresh_window();
        // `Timer::default()` is created at tick 0 with no delay/interval, so
        // its next run is tick 0 — already due at any clock value.
        w.add_timer(TimerId { id: 1 }, Timer::default());
        let clocks: [azul_core::task::GetSystemTimeCallbackType; 3] =
            [time_tick_0, time_tick_1000, time_tick_max];
        for cb in clocks {
            let cb = azul_core::task::GetSystemTimeCallback { cb };
            assert_eq!(w.time_until_next_timer_ms(&cb), Some(0));
        }
    }

    #[test]
    fn time_until_next_timer_ms_takes_the_minimum_across_timers() {
        let mut w = fresh_window();
        w.add_timer(
            TimerId { id: 1 },
            Timer::default().with_interval(tick_dur(5_000)),
        );
        w.add_timer(
            TimerId { id: 2 },
            Timer::default().with_interval(tick_dur(2_000)),
        );
        w.add_timer(
            TimerId { id: 3 },
            Timer::default().with_interval(tick_dur(9_000)),
        );
        // The intervals are in TICKS and the function answers MILLISECONDS, so
        // the expected values convert at the nominal frame rate: 2000 ticks is
        // 2000 * 1000 / 60 = 33_333 ms. They read 2_000 and 1_000 while a tick
        // was assumed to be a millisecond.
        let cb = azul_core::task::GetSystemTimeCallback { cb: time_tick_0 };
        assert_eq!(w.time_until_next_timer_ms(&cb), Some(33_333));

        // At tick 1000 the 2000-tick timer is 1000 ticks away.
        let cb = azul_core::task::GetSystemTimeCallback { cb: time_tick_1000 };
        assert_eq!(w.time_until_next_timer_ms(&cb), Some(16_666));

        // Far past every deadline: overdue => 0.
        let cb = azul_core::task::GetSystemTimeCallback { cb: time_tick_max };
        assert_eq!(w.time_until_next_timer_ms(&cb), Some(0));
    }

    #[test]
    fn time_until_next_timer_ms_does_not_overflow_on_a_max_interval() {
        let mut w = fresh_window();
        w.add_timer(
            TimerId { id: 1 },
            Timer::default().with_interval(tick_dur(u64::MAX)),
        );
        let cb = azul_core::task::GetSystemTimeCallback { cb: time_tick_0 };
        assert_eq!(w.time_until_next_timer_ms(&cb), Some(u64::MAX));
    }

    #[test]
    fn time_until_next_timer_ms_saturates_across_mismatched_clock_kinds() {
        let mut w = fresh_window();
        // Tick-based timer, System-based clock. The mismatch here is between two
        // INSTANTS — `Timer::default()` is created at tick 0 and the clock hands
        // back a wall-clock instant — and those have no common origin, so the
        // span really is undefined and saturates. (A mismatch between the
        // interval's UNIT and the clock's unit is a different thing, and now
        // converts: see `add_optional_duration`.)
        w.add_timer(
            TimerId { id: 1 },
            Timer::default().with_interval(tick_dur(5_000)),
        );
        let cb = azul_core::task::GetSystemTimeCallback {
            cb: time_system_now,
        };
        assert_eq!(w.time_until_next_timer_ms(&cb), Some(0));
    }

    #[test]
    fn breakpoints_crossed_is_symmetric_and_boundary_inclusive() {
        use super::breakpoints_crossed;
        let bp = [720.0_f32];
        assert!(breakpoints_crossed(&bp, 750.0, 600.0), "shrink across");
        assert!(breakpoints_crossed(&bp, 600.0, 750.0), "grow across");
        assert!(!breakpoints_crossed(&bp, 800.0, 730.0), "no crossing above");
        assert!(!breakpoints_crossed(&bp, 600.0, 700.0), "no crossing below");
        // Landing exactly ON the threshold counts as its small side.
        assert!(breakpoints_crossed(&bp, 750.0, 720.0));
        assert!(!breakpoints_crossed(&bp, 720.0, 600.0));
        assert!(
            !breakpoints_crossed(&[], 100.0, 9999.0),
            "no thresholds, no crossings"
        );
    }

    #[test]
    fn window_blur_pauses_the_blink_and_focus_resumes_it_state_intact() {
        use azul_core::task::CURSOR_BLINK_TIMER_ID;
        let mut w = fresh_window();
        // An app (or the engine editing path) armed the blink.
        w.text_edit_manager.blink.set_blink_timer_active(true);
        let ws = w.current_window_state.clone();
        let t = w.create_cursor_blink_timer(&ws);
        w.timers.insert(CURSOR_BLINK_TIMER_ID, t);

        // Blur: the OS timer dies, ALL state stays.
        assert!(w.pause_cursor_blink_for_window_blur());
        assert!(
            w.text_edit_manager.blink.is_blink_timer_active(),
            "the logical flag IS the pause marker"
        );
        assert!(!w.timers.contains_key(&CURSOR_BLINK_TIMER_ID));

        // Refocus: the timer comes back. THE REGRESSION this pins: the old
        // path routed refocus through handle_focus_change_for_cursor_blink,
        // which saw the flag still true and returned NoChange — the killed
        // OS timer stayed dead and the caret never blinked again after the
        // first focus churn (KWin blurs/refocuses around resize grabs).
        let resumed = w.resume_cursor_blink_after_window_focus(&ws);
        assert!(resumed.is_some(), "a paused blink must restart on focus-in");
        assert!(w.timers.contains_key(&CURSOR_BLINK_TIMER_ID));

        // Idempotent: a second FocusIn no-ops instead of double-arming.
        assert!(w.resume_cursor_blink_after_window_focus(&ws).is_none());
    }

    #[test]
    fn focus_churn_does_not_clear_editing_state() {
        // The old refocus path, with engine focus None (an app driving the
        // caret via StartCursorBlinkTimer), ran clear_editing() — caret and
        // selection wiped by a focus flicker. The pause/resume pair must
        // leave the text_edit_manager alone.
        use azul_core::task::CURSOR_BLINK_TIMER_ID;
        let mut w = fresh_window();
        w.text_edit_manager.blink.set_blink_timer_active(true);
        let ws = w.current_window_state.clone();
        let t = w.create_cursor_blink_timer(&ws);
        w.timers.insert(CURSOR_BLINK_TIMER_ID, t);
        w.pause_cursor_blink_for_window_blur();
        let _ = w.resume_cursor_blink_after_window_focus(&ws);
        assert!(
            w.text_edit_manager.blink.is_blink_timer_active(),
            "blink state survives focus churn (the old path dropped it)"
        );
    }

    #[test]
    fn blink_pause_and_resume_are_no_ops_without_an_armed_timer() {
        let mut w = fresh_window();
        assert!(!w.pause_cursor_blink_for_window_blur());
        let ws = w.current_window_state.clone();
        assert!(w.resume_cursor_blink_after_window_focus(&ws).is_none());
    }

    #[test]
    fn create_tooltip_delay_timer_encodes_the_hover_time_as_a_one_shot_delay() {
        let w = fresh_window();
        for ms in [0_u32, 1, 500, u32::MAX] {
            let t = w.create_tooltip_delay_timer(ms);
            assert_eq!(
                t.delay,
                azul_core::task::OptionDuration::Some(sys_dur_ms(u64::from(ms))),
                "hover_time_ms={ms}"
            );
            assert_eq!(
                t.interval,
                azul_core::task::OptionDuration::None,
                "the tooltip timer is one-shot"
            );
            assert_eq!(t.timeout, azul_core::task::OptionDuration::None);
            assert_eq!(t.run_count, 0);
            assert!(matches!(t.last_run, azul_core::task::OptionInstant::None));
            // u32::MAX ms must survive the widening to u64 millis intact.
            match &t.delay {
                azul_core::task::OptionDuration::Some(d) => {
                    assert_eq!(duration_to_millis(*d), u64::from(ms));
                }
                azul_core::task::OptionDuration::None => panic!("delay must be set"),
            }
        }
    }

    #[test]
    fn create_cursor_blink_timer_is_a_repeating_530ms_timer() {
        let w = fresh_window();
        let t = w.create_cursor_blink_timer(&FullWindowState::default());
        assert_eq!(
            t.delay,
            azul_core::task::OptionDuration::None,
            "the blink timer starts immediately"
        );
        assert_eq!(t.timeout, azul_core::task::OptionDuration::None);
        assert_eq!(t.run_count, 0);
        match &t.interval {
            azul_core::task::OptionDuration::Some(d) => assert_eq!(
                duration_to_millis(*d),
                crate::managers::text_edit::CURSOR_BLINK_INTERVAL_MS
            ),
            azul_core::task::OptionDuration::None => panic!("interval must be set"),
        }
    }

    /// The blink timer copies the blink state's interval WHOLE — unit included.
    /// If it flattened to milliseconds, a `caret-animation-duration: 5t` would
    /// reach `Timer::invoke` as a wall-clock span and the exact-frame guarantee
    /// would be gone.
    #[test]
    fn create_cursor_blink_timer_carries_a_tick_interval_through_as_ticks() {
        let mut w = fresh_window();
        w.text_edit_manager
            .blink
            .set_blink_interval(Duration::from_ticks(5));

        let t = w.create_cursor_blink_timer(&FullWindowState::default());
        assert_eq!(
            t.interval,
            azul_core::task::OptionDuration::Some(Duration::from_ticks(5)),
            "the tick unit must survive into the timer"
        );
        // ...and it converts to real milliseconds only where a real OS timer
        // needs one: 5 frames at 60Hz is 83ms, not 5ms.
        assert_eq!(t.tick_millis(), 83);
    }

    /// A `Timer` bakes its interval at construction, so moving focus from a
    /// 250ms caret onto a `5t` one has to REBUILD the timer. The old path
    /// answered `NoChange` whenever a timer was already running, and the caret
    /// went on ticking at the previous node's period for the rest of the
    /// session.
    #[test]
    fn refocusing_between_editables_with_different_blink_rates_restarts_the_timer() {
        let editable = |css: &str| Dom::create_div().with_contenteditable(true).with_css(css);
        let mut w = window_for(StyledDom::create_from_dom(
            Dom::create_body()
                .with_child(editable("caret-animation-duration: 250ms;"))
                .with_child(editable("caret-animation-duration: 5t;"))
                .with_child(editable("caret-animation-duration: 5t;")),
        ));
        let ws = w.current_window_state.clone();

        // Nothing is running yet, so the first focus is a plain Start.
        match w.handle_focus_change_for_cursor_blink(Some(dnid(1)), &ws) {
            CursorBlinkTimerAction::Start(t) => assert_eq!(
                t.interval,
                azul_core::task::OptionDuration::Some(Duration::from_millis(250))
            ),
            other => panic!("expected Start, got {other:?}"),
        }

        // A change of UNIT is a change: `5t` is five FRAMES, not five ms.
        match w.handle_focus_change_for_cursor_blink(Some(dnid(2)), &ws) {
            CursorBlinkTimerAction::Restart(t) => assert_eq!(
                t.interval,
                azul_core::task::OptionDuration::Some(Duration::from_ticks(5)),
                "the rebuilt timer carries the NEWLY focused node's interval"
            ),
            other => panic!("expected Restart, got {other:?}"),
        }

        // Same duration again — rebuilding would restart the blink phase for
        // nothing.
        assert!(matches!(
            w.handle_focus_change_for_cursor_blink(Some(dnid(3)), &ws),
            CursorBlinkTimerAction::NoChange
        ));
    }

    /// `duration_to_millis` must convert ticks at the nominal frame rate. The
    /// old "assume tick = 1ms" made every tick-unit span 16x too short.
    #[test]
    fn duration_to_millis_converts_ticks_at_the_nominal_frame_rate() {
        assert_eq!(duration_to_millis(Duration::from_ticks(60)), 1_000);
        assert_eq!(duration_to_millis(Duration::from_ticks(5)), 83);
        assert_eq!(duration_to_millis(Duration::from_ticks(1)), 16);
        assert_eq!(duration_to_millis(Duration::from_ticks(0)), 0);
        // The wall-clock arm is unchanged.
        assert_eq!(duration_to_millis(Duration::from_millis(530)), 530);
        assert_eq!(duration_to_millis(Duration::from_millis(0)), 0);
    }

