    #[test]
    fn gpu_cache_accessors_are_keyed_per_dom_and_created_on_demand() {
        let mut w = fresh_window();
        let a = DomId { inner: 0 };
        let b = DomId { inner: usize::MAX };
        assert!(w.get_gpu_cache(&a).is_none());
        assert!(w.get_gpu_cache_mut(&a).is_none());

        assert!(w.get_or_create_gpu_cache(a).transform_keys.is_empty());
        assert!(w.get_gpu_cache(&a).is_some());
        assert!(
            w.get_gpu_cache(&b).is_none(),
            "creation must not leak across DOMs"
        );

        // Re-creating returns the same (still empty) cache, not a second one.
        assert!(w.get_or_create_gpu_cache(a).transform_keys.is_empty());
        assert!(w.get_or_create_gpu_cache(b).transform_keys.is_empty());
        assert!(w.get_gpu_cache(&b).is_some());
    }

    #[test]
    fn layout_result_accessors_track_get_dom_ids() {
        let mut w = fresh_window();
        assert!(w.get_layout_result(&DomId::ROOT_ID).is_none());
        assert!(w.get_layout_result_mut(&DomId::ROOT_ID).is_none());
        assert_eq!(w.get_dom_ids().len(), 0);

        w.layout_results
            .insert(DomId::ROOT_ID, bare_layout_result(fixture_dom()));
        assert!(w.get_layout_result(&DomId::ROOT_ID).is_some());
        assert!(w.get_layout_result_mut(&DomId::ROOT_ID).is_some());
        assert_eq!(w.get_dom_ids().len(), 1);
        assert!(w.get_layout_result(&DomId { inner: 1 }).is_none());
    }

    // ==================================================================
    // Edge / error arms exercised by the headless e2e_json harness at the
    // integration level, pinned here as fast unit checks (no fonts, no
    // solver where avoidable). These cover the "nothing there" / degenerate
    // branches a happy-path fixture never reaches.
    // ==================================================================

    /// Run the real layout pipeline on a `StyledDom` at a given viewport.
    fn laid_out(styled_dom: StyledDom, w: f32, h: f32) -> LayoutWindow {
        let mut win = fresh_window();
        let mut ws = FullWindowState::default();
        ws.size.dimensions = size(w, h);
        let rr = RendererResources::default();
        let sc = ExternalSystemCallbacks::rust_internal();
        let mut dbg = None;
        win.layout_and_generate_display_list(styled_dom, &ws, &rr, &sc, &mut dbg)
            .expect("layout must succeed on a well-formed DOM");
        win
    }

    /// THE CLASS (azpaint pressure meter, 2026-08-29): a `VirtualView` child
    /// DOM was laid out against the WINDOW viewport, not the view's own
    /// bounds — a percent-width child of the returned root resolved against
    /// the window (66% of 640 instead of 66% of 140) and painted "full
    /// width" after clipping. The child viewport must be the VV bounds: the
    /// returned root fills the view, and percentages resolve inside it.
    #[test]
    fn a_virtual_view_child_lays_out_against_the_view_bounds_not_the_window() {
        use azul_core::callbacks::{VirtualViewCallbackInfo, VirtualViewReturn};
        use azul_core::refany::RefAny;

        extern "C" fn half_split(
            _data: RefAny,
            info: VirtualViewCallbackInfo,
        ) -> VirtualViewReturn {
            let size = info.bounds.get_logical_size();
            let rect = LogicalRect::new(LogicalPosition::zero(), size);
            let dom = Dom::create_div()
                .with_css("display: flex; flex-direction: row; height: 20px;")
                .with_child(Dom::create_div().with_css("width: 50%; height: 20px;"))
                .with_child(Dom::create_div().with_css("width: 50%; height: 20px;"));
            VirtualViewReturn::with_dom(dom, rect, rect)
        }

        // body(0) > wrapper div(1, 140px wide) > virtual view(2, fills wrapper)
        let dom = Dom::create_body().with_child(
            Dom::create_div()
                .with_css("width: 140px; height: 20px;")
                .with_child(
                    Dom::create_virtual_view(
                        RefAny::new(0_u8),
                        azul_core::callbacks::VirtualViewCallback::create(half_split),
                    )
                    .with_css("width: 100%; height: 20px;"),
                ),
        );
        let win = laid_out(StyledDom::create_from_dom(dom), 640.0, 480.0);

        // The materialized child DOM is the first nested dom id.
        let child_dom = win
            .get_dom_ids()
            .as_ref()
            .iter()
            .copied()
            .find(|d| d.inner != 0)
            .expect("the VirtualView must have materialized a child DOM");
        let node = |n: usize| DomNodeId {
            dom: child_dom,
            node: NodeHierarchyItemId::from_crate_internal(Some(NodeId::new(n))),
        };

        // child root(0) > bar(1) + rest(2)
        let root = win.get_node_size(node(0)).expect("child root laid out");
        assert!(
            (root.width - 140.0).abs() < 1.0,
            "the child ROOT must fill the view bounds (140px), got {root:?} — \
             a window-sized root means percents resolve against the window"
        );
        let bar = win.get_node_size(node(1)).expect("bar laid out");
        assert!(
            (bar.width - 70.0).abs() < 1.0,
            "width:50% inside a 140px view must be 70px, got {bar:?} \
             (320px = it resolved against the 640px window)"
        );
        let rest = win.get_node_size(node(2)).expect("rest laid out");
        assert!(
            (rest.width - 70.0).abs() < 1.0,
            "the second 50% child must also be 70px, got {rest:?}"
        );
    }

    /// THE CLASS (AzWidgets "TextInput not working", 2026-08-21): an IFC root
    /// with an EMPTY text run produced no inline layout and zero height, so a
    /// focused empty editable had no line for its caret and collapsed to its
    /// chrome. Inside an editing host the empty IFC now keeps a strut line
    /// box: an (item-less) inline layout and one line-height of height. A
    /// non-editable twin still renders nothing — the strut is not a general
    /// "empty blocks get height" rule.
    #[test]
    fn an_empty_editing_host_keeps_a_strut_line_box() {
        fn host(editable: bool) -> StyledDom {
            let mut inner = Dom::create_div()
                .with_child(Dom::create_text_do_not_use_without_block_level_wrapper(""));
            if editable {
                inner = inner.with_contenteditable(true);
            }
            StyledDom::create_from_dom(Dom::create_body().with_child(inner))
        }
        // body(0) > div(1) > text(2)
        let inner = NodeId::new(1);
        let dnid = DomNodeId {
            dom: DomId::ROOT_ID,
            node: NodeHierarchyItemId::from_crate_internal(Some(inner)),
        };

        let win = laid_out(host(true), 400.0, 300.0);
        let size = win
            .get_node_size(dnid)
            .expect("the editable div is laid out");
        assert!(
            size.height > 8.0 && size.height < 48.0,
            "an empty editing host keeps ONE line of height (the strut), got {size:?}"
        );
        let layout = win
            .get_inline_layout_for_node(DomId::ROOT_ID, inner)
            .expect("an empty editing host keeps an inline layout for its caret");
        assert!(
            layout.items.is_empty(),
            "…with no items: the caret painter's strut branch"
        );
        // ...and with CONSTRAINTS, so the first keystroke has a line box to
        // be shaped into (`reshape_text_node` drops an edit whose IFC carries
        // none — which is how an empty TextInput ate its first character).
        let lr = win
            .layout_results
            .get(&DomId::ROOT_ID)
            .expect("layout result");
        let idx = *lr
            .layout_tree
            .dom_to_layout
            .get(&inner)
            .and_then(|v| v.first())
            .expect("mapped");
        let cached = lr
            .layout_tree
            .warm(idx)
            .and_then(|w| w.inline_layout_result.as_ref())
            .expect("cached inline layout");
        assert!(
            cached.constraints.is_some(),
            "the strut line box carries the IFC's constraints like any other line box"
        );

        let plain = laid_out(host(false), 400.0, 300.0);
        let size = plain
            .get_node_size(dnid)
            .expect("the plain div is laid out");
        assert!(
            size.height.abs() < 0.5,
            "a non-editable empty block still collapses to zero height, got {size:?}"
        );
        assert!(
            plain
                .get_inline_layout_for_node(DomId::ROOT_ID, inner)
                .is_none(),
            "…and keeps no inline layout (an empty IFC renders nothing)"
        );
    }

    /// `(y, height)` of DOM node `index` (pre-order) in a laid-out window.
    fn y_and_height(win: &LayoutWindow, index: usize) -> (f32, f32) {
        let dnid = DomNodeId {
            dom: DomId::ROOT_ID,
            node: NodeHierarchyItemId::from_crate_internal(Some(NodeId::new(index))),
        };
        let pos = win.get_node_position(dnid).expect("laid out");
        let size = win.get_node_size(dnid).expect("laid out");
        (pos.y, size.height)
    }

    /// CSS 2.2 §8.3.1: an EMPTY block's top and bottom margins collapse
    /// through each other and with its neighbours': a(50, mb 10) /
    /// empty(mt 20, mb 30) / b(mt 5) puts b at a + 50 + max(10, 20, 30, 5).
    #[test]
    fn an_empty_block_between_siblings_collapses_every_margin_to_the_max() {
        let dom = Dom::create_body()
            .with_child(Dom::create_div().with_css("height: 50px; margin-bottom: 10px;"))
            .with_child(Dom::create_div().with_css("margin-top: 20px; margin-bottom: 30px;"))
            .with_child(Dom::create_div().with_css("height: 50px; margin-top: 5px;"));
        let win = laid_out(StyledDom::create_from_dom(dom), 400.0, 300.0);
        // body(0) > a(1), empty(2), b(3)
        let (a_y, _) = y_and_height(&win, 1);
        let (e_y, e_h) = y_and_height(&win, 2);
        let (b_y, _) = y_and_height(&win, 3);
        assert!(e_h.abs() < 0.5, "an empty block is zero tall: {e_h}");
        assert!(
            (b_y - a_y - 80.0).abs() < 0.5,
            "b must start 50 + max(10, 20, 30, 5) = 80 below a, got {}",
            b_y - a_y
        );
        assert!(
            (e_y - a_y) >= 50.0 && (e_y - a_y) <= 80.5,
            "the empty block sits inside the seam: {}",
            e_y - a_y
        );
    }

    /// THE CLASS (AzWidgets 2026-08-21, "placeholder drawn low"): an EMPTY
    /// FIRST child under a parent with a top blocker (padding). Its
    /// collapsed-through margin is ONE margin inside the parent's content
    /// box: 4 + 13 + 4 = 21 (Chrome: 21); the pen used to advance by the
    /// margin AND carry it for the parent's bottom padding to add again.
    #[test]
    fn an_empty_first_child_inside_a_padded_parent_counts_its_margin_once() {
        let dom = Dom::create_body().with_child(
            Dom::create_div()
                .with_css("padding: 4px;")
                .with_child(Dom::create_div().with_css("margin-top: 13px; margin-bottom: 13px;")),
        );
        let win = laid_out(StyledDom::create_from_dom(dom), 400.0, 300.0);
        // body(0) > wrap(1) > e(2)
        let (wrap_y, wrap_h) = y_and_height(&win, 1);
        let (e_y, _) = y_and_height(&win, 2);
        assert!(
            (wrap_h - 21.0).abs() < 0.5,
            "padding 4 + ONE collapsed margin 13 + padding 4 = 21, got {wrap_h}"
        );
        assert!(
            (e_y - wrap_y - 17.0).abs() < 0.5,
            "the empty block's border edges sit after its top margin: 4 + 13 = 17, got {}",
            e_y - wrap_y
        );

        // After a sibling, under the same padded parent: counted once too.
        let dom = Dom::create_body().with_child(
            Dom::create_div()
                .with_css("padding: 4px;")
                .with_child(Dom::create_div().with_css("height: 10px;"))
                .with_child(Dom::create_div().with_css("margin-top: 13px; margin-bottom: 13px;")),
        );
        let win = laid_out(StyledDom::create_from_dom(dom), 400.0, 300.0);
        let (_, wrap_h) = y_and_height(&win, 1);
        assert!(
            (wrap_h - 31.0).abs() < 0.5,
            "4 + 10 + 13 + 4 = 31, got {wrap_h}"
        );

        // And the parent's OWN top margin never leaks into its content box
        // through an empty first child (the "feet to meters" mix).
        let dom = Dom::create_body().with_child(
            Dom::create_div()
                .with_css("margin-top: 40px; padding: 4px;")
                .with_child(Dom::create_div().with_css("margin-top: 13px; margin-bottom: 13px;")),
        );
        let win = laid_out(StyledDom::create_from_dom(dom), 400.0, 300.0);
        let (_, wrap_h) = y_and_height(&win, 1);
        assert!(
            (wrap_h - 21.0).abs() < 0.5,
            "the parent's margin is not added inside it: {wrap_h}"
        );
    }

